StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Interlock                                                                    																																									
//	CREATOR:		Helgevold - Ruben Byman                                                                                                                                                                                                                                                        
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2025-03-24		Ruben Byman			Initial release
//	2.0.0				2025-08-19		William Veim			Total rework
//	2.0.1				2025-08-28		Ruben Byman			Bug fix digital interlock
//	2.0.2				2025-08-29		William Veim			Bugfix regarding increasing number of triggers
//	2.0.3				2025-09-05		William Veim			Bugfix trigger condition ("InUse" added as condtion)
//	2.1.0				2025-09-05		William Veim			Added logic for VFD triggers
// 2.1.1				2026-14-01		William Veim			Analog trigger bugfix
// 3.0.0				2026-17-04		William Veim			Total rework - Only 10 triggers including selection of trigger type
//	3.0.1				2026-06-25		Ruben Byman			Bugfix first active
//
//===============================================================================================================================
//
//		FUNCTION:
//		*	Interlock function based on up to 8 triggers (analog or digital)
//		*	Per trigger, write to Triggers.Interlock_Triggers[x].Cfg_Type (#USINT 0, 1, 2 or 3) and .AnalogTrigger or .DigitalTrigger outside of this FB
//		*	Cfg_Types: 0 = Not in use, 1 = Digital trigger (TRUE = interlock), 2 = Analog trigger above limit, 3 = Analog trigger below limit
//		*	Delay of both activation and reset independently per trigger
//		*	Latching optional per trigger, latching requires manual reset
//
//===============================================================================================================================

(*************************************************************************
 *	INITIALISING VARIABELS
 *************************************************************************)

Ext_Interlock.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining three optional can be set in SCADA
Ext_Interlock.EXT_Operator.Sts_Bypassed := FALSE;
Ext_Interlock.EXT_Operator.Sts_Interlocked:= FALSE;

(*************************************************************************
 *	INTERLOCK DATA UPDATE
 *************************************************************************)

FOR Index := DINT_TO_USINT(LOWER_BOUND(Ext_Interlock.EXT_Engineering.TriggerData, 1)) TO DINT_TO_USINT(UPPER_BOUND(Ext_Interlock.EXT_Engineering.TriggerData, 1)) DO
	
	CASE Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_TriggerType OF 
		
		0: //NOT IN USE
		
			Wrk_Trigger[Index]:=FALSE;
		
		1: //DIGITAL TRIGGER
		CASE Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueStateIndex OF 
			
			0://State 1
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_1.Sts_State;
			
			1://State 2
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_2.Sts_State;
			
			2://State 3
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_3.Sts_State;
			
			3://State 4
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_4.Sts_State;
			
			4://State 5
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_5.Sts_State;
			
			5://State 6
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_6.Sts_State;
			
			6://State 7
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_7.Sts_State;
			
			7://State 8
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_8.Sts_State;
			
			8://State 9
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_9.Sts_State;
			
			9://State 10
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_10.Sts_State;
			
			10://State 11
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_11.Sts_State;
			
			11://State 12
			Wrk_Trigger[Index]:= EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_12.Sts_State;
			
		END_CASE;
		
		2: //DIGITAL TRIGGER INVERTED
			CASE Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueStateIndex OF 
			
			0://State 1
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_1.Sts_State;
			
			1://State 2
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_2.Sts_State;
			
			2://State 3
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_3.Sts_State;
			
			3://State 4
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_4.Sts_State;
			
			4://State 5
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_5.Sts_State;
			
			5://State 6
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_6.Sts_State;
			
			6://State 7
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_7.Sts_State;
			
			7://State 8
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_8.Sts_State;
			
			8://State 9
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_9.Sts_State;
			
			9://State 10
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_10.Sts_State;
			
			10://State 11
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_11.Sts_State;
			
			11://State 12
			Wrk_Trigger[Index]:= NOT EXT_DigitalValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_12.Sts_State;
			
			END_CASE;
		
		3: //VFD TRIGGER
			CASE Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueStateIndex OF 
			
			0://State 1
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_1.Sts_State;
			
			1://State 2
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_2.Sts_State;
			
			2://State 3
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_3.Sts_State;
			
			3://State 4
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_4.Sts_State;
			
			4://State 5
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_5.Sts_State;
			
			5://State 6
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_6.Sts_State;
			
			6://State 7
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_7.Sts_State;
			
			7://State 8
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_8.Sts_State;
			
			8://State 9
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_9.Sts_State;
			
			9://State 10
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_10.Sts_State;
			
			10: //Hardcoded "Local mode"
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_General.Remote;
			
			11: //Hardcoded "Running"
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_General.Running;
			
			END_CASE;
		
		4: //VFD TRIGGER INVERTED
			CASE Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueStateIndex OF 
			
			0://State 1
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_1.Sts_State;
			
			1://State 2
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_2.Sts_State;
			
			2://State 3
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_3.Sts_State;
			
			3://State 4
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_4.Sts_State;
			
			4://State 5
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_5.Sts_State;
			
			5://State 6
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_6.Sts_State;
			
			6://State 7
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_7.Sts_State;
			
			7://State 8
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_8.Sts_State;
			
			8://State 9
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_9.Sts_State;
			
			9://State 10
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_10.Sts_State;
			
			10: //Hardcoded "Local mode"
			Wrk_Trigger[Index]:= EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_General.Remote;
			
			11: //Hardcoded "Running"
			Wrk_Trigger[Index]:= NOT EXT_VFD[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_General.Running;
			
			END_CASE; 
		
		5: //ANALOG STATE
			CASE Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueStateIndex OF 
			
			0://State 1
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_1.Sts_State;
			
			1://State 2
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_2.Sts_State;
			
			2://State 3
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_3.Sts_State;
			
			3://State 4
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_4.Sts_State;
			
			4://State 5
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_5.Sts_State;
			
			5://State 6
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_6.Sts_State;
			
			6://State 7
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_7.Sts_State;
			
			7://State 8
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_8.Sts_State;
			
			8://State 9
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_9.Sts_State;
			
			9://State 10
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_10.Sts_State;
			
			10://State 11
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_11.Sts_State;
			
			11://State 12
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Engineering.StateCfg_12.Sts_State;
			
			END_CASE; 
		
		6: //ANALOG VALUE OVER LIMIT
		
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Operator.ProcessValue > Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_Trig_AnaLimit;
		
		7: //ANALOG VALUE UNDER LIMIT
		
			Wrk_Trigger[Index]:= EXT_AnalogValue[Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex].EXT_Operator.ProcessValue < Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_Trig_AnaLimit;
		
		8: //CUSTOM
		CASE Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ValueIndex OF
			
			1: //Custom value 1
			Wrk_Trigger[Index]:= Inp_CustomTrigger1;
			Ext_Interlock.EXT_Engineering.TriggerData[Index].Sts_CustomValue:=Inp_CustomTrigger1;
			Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_Trig_Description:=Cfg_CustomSuffix1;
			
			2: //Custom value 2
			Wrk_Trigger[Index]:= Inp_CustomTrigger2;
			Ext_Interlock.EXT_Engineering.TriggerData[Index].Sts_CustomValue:=Inp_CustomTrigger2;
			Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_Trig_Description:=Cfg_CustomSuffix2;
			
			3: //Custom value 3
			Wrk_Trigger[Index]:= Inp_CustomTrigger3;
			Ext_Interlock.EXT_Engineering.TriggerData[Index].Sts_CustomValue:=Inp_CustomTrigger3;
			Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_Trig_Description:=Cfg_CustomSuffix3;
			
			4: //Custom value 4
			Wrk_Trigger[Index]:= Inp_CustomTrigger4;
			Ext_Interlock.EXT_Engineering.TriggerData[Index].Sts_CustomValue:=Inp_CustomTrigger4;
			Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_Trig_Description:=Cfg_CustomSuffix4;
			
			5: //Custom value 5
			Wrk_Trigger[Index]:= Inp_CustomTrigger5;
			Ext_Interlock.EXT_Engineering.TriggerData[Index].Sts_CustomValue:=Inp_CustomTrigger5;
			Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_Trig_Description:=Cfg_CustomSuffix5;
			
		END_CASE;
	END_CASE;
	
	//Trigger delay
	//-------------------------------------------------------------
	
	TON_Trig_Activate[Index](In:=Wrk_Trigger[Index], 
											PT:=SecToTime(Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_TrigDelay));
	
	TON_Trig_Return[Index](In:=NOT Wrk_Trigger[Index], 
											PT:=SecToTime(Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_ReturnDelay));

	
	//Overwrite bypass activated per trigger if not allowed
	//----------------------------------------------------------

	IF NOT Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_Bypassable THEN
		Ext_Interlock.EXT_Operator.TriggerData[Index].Cfg_Bypass := FALSE;
	END_IF;
	
END_FOR;


(*************************************************************************
 *	TRIGGER STATE CONTROL
 *************************************************************************)

FOR Index := DINT_TO_USINT(LOWER_BOUND(Ext_Interlock.EXT_Engineering.TriggerData, 1)) TO DINT_TO_USINT(UPPER_BOUND(Ext_Interlock.EXT_Engineering.TriggerData, 1)) DO
	
	CASE Ext_Interlock.EXT_Operator.TriggerData[Index].Sts_State OF
		
		0://CURRENT STATE IS - NORMAL
			Ext_Interlock.EXT_Operator.TriggerData[Index].Sts_FirstActive:=FALSE;
			
			//Moving to bypass state
			IF  Ext_Interlock.EXT_Operator.TriggerData[Index].Cfg_Bypass AND Ext_Interlock.EXT_Operator.Cfg_BypassEnable THEN
				Ext_Interlock.EXT_Operator.TriggerData[Index].Sts_State:=1;
			END_IF;
			
			//Moving to interlock state
			IF TON_Trig_Activate[Index].Q THEN
				Ext_Interlock.EXT_Operator.TriggerData[Index].Sts_State:=2;
				IF NOT Wrk_FirstActiveFound THEN
					Ext_Interlock.EXT_Operator.TriggerData[Index].Sts_FirstActive:=TRUE;
					Wrk_FirstActiveFound:=TRUE;
				END_IF;
			END_IF;
		
		1://CURRENT STATE IS - BYPASSED
		
			//Moving to normal state
			IF  NOT Ext_Interlock.EXT_Operator.TriggerData[Index].Cfg_Bypass OR NOT Ext_Interlock.EXT_Operator.Cfg_BypassEnable THEN
				Ext_Interlock.EXT_Operator.TriggerData[Index].Sts_State:=0;
			END_IF;
		
		2://CURRENT STATE IS - INTERLOCKED
			
			//Moving to bypass state
			IF  Ext_Interlock.EXT_Operator.TriggerData[Index].Cfg_Bypass AND Ext_Interlock.EXT_Operator.Cfg_BypassEnable THEN
				Ext_Interlock.EXT_Operator.TriggerData[Index].Sts_State:=1;
			END_IF;
				
			//Moving to normal state
			IF (NOT TON_Trig_Activate[Index].Q AND TON_Trig_Return[Index].Q AND NOT Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_Latch) //Normal return
				OR (NOT TON_Trig_Activate[Index].Q AND TON_Trig_Return[Index].Q AND Ext_Interlock.EXT_Engineering.TriggerData[Index].Cfg_Latch AND Ext_Interlock.EXT_Operator.Cfg_ResetLatched)THEN //Return with latch
				Ext_Interlock.EXT_Operator.TriggerData[Index].Sts_State:=0;
			END_IF;

	END_CASE;

	//Updates output
	//--------------------------
	
	IF Ext_Interlock.EXT_Operator.Cfg_BypassEnable AND Ext_Interlock.EXT_Operator.TriggerData[Index].Cfg_Bypass THEN
		Ext_Interlock.EXT_Operator.Sts_Bypassed := TRUE;
	END_IF;
	
	IF Ext_Interlock.EXT_Operator.TriggerData[Index].Sts_State = 2 THEN
		Ext_Interlock.EXT_Operator.Sts_Interlocked:= TRUE;
	END_IF;

END_FOR;

(*************************************************************************
 *	UPDATING OUTPUT
 *************************************************************************)
 
Ext_Interlock.EXT_Operator.Cfg_ResetLatched:=FALSE;
Sts_Interlock:=Ext_Interlock.EXT_Operator.Sts_Interlocked;
Sts_Bypassed:=Ext_Interlock.EXT_Operator.Sts_Bypassed;

IF NOT Sts_Interlock THEN
	Wrk_FirstActiveFound:=FALSE;
END_IF;
